Author:     welpy-cw <h.w.forms@arcor.de>
AuthorDate: Tue May 13 11:13:38 2025 +0000
Commit:     welpy-cw <h.w.forms@arcor.de>
CommitDate: Tue May 13 11:13:38 2025 +0000

    Bug 1949609 - Follow-up: Some regression fixes. r=BenC,mkmelin


    - Unified folders covering a folder don't show any messages if an included folder has been compacted.
    - Selected messages were not restored upon refresh of the view.

    Differential Revision: https://phabricator.services.mozilla.com/D248768

diff --git a/mail/modules/DBViewWrapper.sys.mjs b/mail/modules/DBViewWrapper.sys.mjs
index 3399f58eabb..100cbabe14a 100644
--- a/mail/modules/DBViewWrapper.sys.mjs
+++ b/mail/modules/DBViewWrapper.sys.mjs
@@ -1372,17 +1372,19 @@ DBViewWrapper.prototype = {
    * to be rebuilt. We want to notify our listener so they have a chance to
    * save the selected messages.
    */
-  _aboutToCompactFolder(_aFolder) {
-    // we will have to re-create the view, so nuke the view now.
-    if (this.dbView) {
-      // Save the view's flags that will be restored in
-      // _compactedFolder(aFolder).
-      this.__viewFlags = this.dbView.viewFlags;
-      this.listener.onDestroyingView(true);
-      this.search.dissociateView(this.dbView);
-      this.dbView.close();
-      this.dbView = null;
+  _aboutToCompactFolder(aFolder) {
+    if (aFolder != this.displayedFolder || !this.dbView) {
+      return;
     }
+
+    // Save the view's flags that will be restored in
+    // _compactedFolder(aFolder).
+    this.__viewFlags = this.dbView.viewFlags;
+    // We will have to re-create the view, so nuke the view now.
+    this.listener.onDestroyingView(true);
+    this.search.dissociateView(this.dbView);
+    this.dbView.close();
+    this.dbView = null;
   },

   /**
diff --git a/mailnews/base/src/FolderCompactor.cpp b/mailnews/base/src/FolderCompactor.cpp
index 0826fd5368b..a327be7b271 100644
--- a/mailnews/base/src/FolderCompactor.cpp
+++ b/mailnews/base/src/FolderCompactor.cpp
@@ -180,6 +180,7 @@ nsresult FolderCompactor::BeginCompacting(
   // Just in case we exit early...
   auto guardSemaphore = mozilla::MakeScopeExit([&] {
     mFolder->ReleaseSemaphore(this, "FolderCompactor::BeginCompacting"_ns);
+    mFolder->NotifyCompactCompleted();
   });

   // If it's a local folder and the DB needs to be rebuilt, this will fail.
@@ -218,6 +219,8 @@ nsresult FolderCompactor::BeginCompacting(
   rv = BuildKeepMap(db, mMsgsToKeep);
   NS_ENSURE_SUCCESS(rv, rv);

+  mFolder->NotifyAboutToCompact();
+
   // We've read what we need from the DB now. Close it. We'll be working on a
   // copy from now on.
   mFolder->ForceDBClosed();
@@ -308,7 +311,6 @@ nsresult FolderCompactor::BeginCompacting(
   if (notifier) {
     notifier->NotifyFolderCompactStart(mFolder);
   }
-  mFolder->NotifyAboutToCompact();

   guardSemaphore.release();
   return NS_OK;
